Vector2 Choose(int turn){
 float best=float.NegativeInfinity;Vector2 chosen=Vector2.up;
 for(int a=12;a<=168;a+=3){float radians=a*Mathf.Deg2Rad;Vector2 direction=new Vector2(Mathf.Cos(radians),Mathf.Sin(radians)),d=direction,p=g.SpawnPosition(direction);float score=0,distance=70;Collider2D previous=null;var health=new Dictionary<int,int>();var opened=new HashSet<int>();
  for(int bounce=0;bounce<40&&distance>.01f;bounce++){
   var hits=Physics2D.CircleCastAll(p,FlightGeometry.Radius,d,distance,1<<8);RaycastHit2D hit=default;bool found=false;
   foreach(var candidate in hits.OrderBy(h=>h.distance)){if(candidate.collider==null||candidate.collider.isTrigger||candidate.distance<.005f&&candidate.collider==previous)continue;var brick=candidate.collider.GetComponentInParent<BrickBody>();if(brick!=null&&(!brick.Alive||health.TryGetValue(brick.Id,out int gone)&&gone<=0))continue;hit=candidate;found=true;break;}
   if(!found||d.y<0&&hit.centroid.y<-6.1f)break;distance-=Mathf.Max(.02f,hit.distance);var b=hit.collider.GetComponentInParent<BrickBody>();
   if(b!=null){if(!health.TryGetValue(b.Id,out int hp))hp=b.CurrentHealth;if(b.Definition.kind==BrickKind.Stone)score-=.25f;else if(b.Definition.kind==BrickKind.RearWeak&&!g.ChainRearEntry(b,d,hit.point))score-=.35f;else if(b.ShellIntact&&!opened.Contains(b.Id)){opened.Add(b.Id);score+=2;}else{int damage=b.Definition.kind==BrickKind.RearWeak?hp:1;score+=(b.Definition.juiceGroup>0||g.IsJellyTarget(b))?2f:ChainPowerRules.IsNest(b.Definition)?1.1f:.7f;hp-=damage;health[b.Id]=hp;if(hp<=0)score+=(b.Definition.juiceGroup>0||g.IsJellyTarget(b))?12:3;}}
   else if(hit.collider.GetComponentInParent<ChainCubeView>()!=null)score+=6;
   previous=hit.collider;d=Vector2.Reflect(d,hit.normal).normalized;p=hit.centroid+hit.normal*.02f;
  }
  // Alternate equally good symmetric routes without relying on a hidden random seed.
  score+=Mathf.Sin((a+turn*23)*.12f)*.08f;if(score>best){best=score;chosen=direction;}
 }
 return chosen;
}

public void Begin(){Guard(()=>{
 if(!initialized||game.IsTutorial||game.IsStreakTrial)return;
 Finish("restarted");lastLoss=null;generation=game.Generation;launch=null;
 string config=Configuration(game),hash=BalanceReport.Hash(config);int level=game.LevelIndex+1;
 var previous=History.rounds.Where(r=>r.level==level).ToArray();
 var tally=History.attempts.FirstOrDefault(t=>t.level==level&&t.configHash==hash);
 if(tally==null){tally=new BalanceAttempt{level=level,configHash=hash,count=previous.Where(r=>r.configHash==hash).Select(r=>r.configAttempt).DefaultIfEmpty(0).Max()};History.attempts.Add(tally);}tally.count++;
 History.active=new BalanceRound{id=Guid.NewGuid().ToString("N"),startedUtc=DateTime.UtcNow.ToString("o"),version=GameVersion.Name,configJson=config,configHash=hash,level=level,attempt=Math.Max(previous.Select(r=>r.attempt).DefaultIfEmpty(0).Max()+1,History.attempts.Where(t=>t.level==level).Sum(t=>t.count)),configAttempt=tally.count,initialShots=game.Shots,remainingShots=game.Shots,initialSpecials=Specials(),streakTier=game.UsesShopBoosters?app.Profile.CampaignStreakTier:0,outcome="in_progress"};
 BeginStrategy();initialGenerated=game.ChainGeneratedCount;lastStock=Stock();Capture();dirty=true;nextSave=Time.unscaledTime;
});}

