 foreach(var loot in chainLoot.ToArray()){
  loot.Age+=dt;float t=Mathf.Clamp01(loot.Age/.6f);Vector2 target=loot.OpeningTarget>=0?(OpeningLootDestination!=null?OpeningLootDestination(loot.OpeningTarget):new Vector2(0,7.95f)):loot.JellyColor>=0?(JellyLootDestination!=null?JellyLootDestination(loot.JellyColor):new Vector2(-2.4f,7.95f)):(ChainLootDestination!=null?ChainLootDestination(loot.Kind):new Vector2(loot.Kind==1?-1.35f:1.6f,7.95f));
  if(IsOpening||IsTutorial){CollectionFlightMotion.Apply(loot,target,IsOpening&&loot.OpeningTarget>=0?OpeningTargets[loot.OpeningTarget].kind:"ordinary_color");}else loot.View.position=Vector2.Lerp(loot.Start,target,t*t)+Vector2.up*(Mathf.Sin(t*Mathf.PI)*.7f);
  float absorb=Mathf.Sin(Mathf.Clamp01((t-.78f)/.22f)*Mathf.PI)*.28f;if(!IsOpening&&!IsTutorial)loot.View.localScale=new Vector3(1+absorb,1-absorb,1)*Mathf.Lerp(.55f,.25f,t);
  if(t>=1){SoundService.Play("collect_arrive");if(loot.OpeningTarget>=0){if(loot.StrategyCredit!=null)loot.StrategyCredit();else OpeningCreditTarget(loot.OpeningTarget);}else if(loot.JellyColor>=0)CollectJelly(loot.JellyColor);else{if(Collected[loot.Kind-1]<CollectionGoal[loot.Kind-1]&&Collected[loot.Kind-1]+1>=CollectionGoal[loot.Kind-1])SoundService.Play("goal_complete");Collected[loot.Kind-1]=Mathf.Min(CollectionGoal[loot.Kind-1],Collected[loot.Kind-1]+1);}if(!IsOpening&&!IsTutorial){ChainVisualArt.Effect(this,2,3,target,.7f);ChainVisualArt.Glint(this,target,3,.28f);EmitFeedback(target,"break",loot.JellyColor>=0?JellyCollectionArt.Color(loot.JellyColor):loot.Kind==1?new Color(1,.73f,.3f):new Color(1,.58f,.68f));}Destroy(loot.View.gameObject);chainLoot.Remove(loot);changed=true;}
 }
 TickChainGravity(dt);
