static float Evaluate(GameSession game,BrickBody[] bricks,float angle){
 var targets=bricks.Select(b=>new Target{d=b.Definition,p=b.transform.position,hp=b.CurrentHealth,charge=game.CoreCharge(b),shell=b.ShellIntact}).ToArray();float score=0;
 var direction=new Vector2(Mathf.Cos(angle*Mathf.Deg2Rad),Mathf.Sin(angle*Mathf.Deg2Rad));
 for(int ball=0;ball<5;ball++){
  Vector2 p=game.SpawnPosition(direction),v=direction;float distance=game.CurrentLevel.ballSpeed*9;int heat=0;
  for(int bounce=0;bounce<80&&distance>0;bounce++){
   float near=distance;Vector2 normal=Vector2.zero;Target hit=null;
   float wall=v.x>0?(3.938f-p.x)/v.x:v.x<0?(-3.938f-p.x)/v.x:float.MaxValue;if(wall>.0001f&&wall<near){near=wall;normal=v.x>0?Vector2.left:Vector2.right;}
   float top=v.y>0?(7.328f-p.y)/v.y:v.y<0?(-6.1f-p.y)/v.y:float.MaxValue;if(top>.0001f&&top<near){near=top;normal=v.y>0?Vector2.down:Vector2.up;}
   foreach(var t in targets)if(!t.dead){
    // Conservative expanded square; guide geometry is checked by real physics later.
    float half=t.d.kind==BrickKind.Guide?.269f:.3f;float h=half+FlightGeometry.Radius;Vector2 lo=t.p-Vector2.one*h,hi=t.p+Vector2.one*h;
    float tx1=v.x==0?float.NegativeInfinity:(lo.x-p.x)/v.x,tx2=v.x==0?float.PositiveInfinity:(hi.x-p.x)/v.x;
    float ty1=v.y==0?float.NegativeInfinity:(lo.y-p.y)/v.y,ty2=v.y==0?float.PositiveInfinity:(hi.y-p.y)/v.y;
    if(v.x==0&&(p.x<lo.x||p.x>hi.x)||v.y==0&&(p.y<lo.y||p.y>hi.y))continue;
    float tx=Mathf.Min(tx1,tx2),ty=Mathf.Min(ty1,ty2),entry=Mathf.Max(tx,ty),exit=Mathf.Min(Mathf.Max(tx1,tx2),Mathf.Max(ty1,ty2));
    if(entry>.0001f&&entry<=exit&&entry<near){near=entry;hit=t;normal=tx>ty?(v.x>0?Vector2.left:Vector2.right):(v.y>0?Vector2.down:Vector2.up);}
   }
   p+=v*near;distance-=near;if(normal==Vector2.zero||p.y<=-6.09f&&v.y<0)break;
   v=Vector2.Reflect(v,normal).normalized;p+=normal*.002f;
   if(hit==null)continue;heat++;int damage=heat>=8?3:heat>=4?2:1;
   if(hit.d.kind==BrickKind.Core){hit.charge++;score+=.35f;if(hit.charge<3)continue;damage=99;}
   var queue=new Queue<Target>();score+=Damage(hit,damage,queue);
   if(hit.d.kind==BrickKind.Resonance)foreach(var t in targets)if(t!=hit&&!t.dead&&t.d.kind==BrickKind.Resonance&&t.d.juiceGroup==hit.d.juiceGroup)score+=Damage(t,1,queue);
   while(queue.Count>0){var source=queue.Dequeue();var d=source.d;
    foreach(var t in targets)if(!t.dead){int dr=Mathf.Abs(d.referenceRow-t.d.referenceRow),dc=Mathf.Abs(d.referenceCol-t.d.referenceCol);bool affect=d.kind==BrickKind.Switch?t.d.kind==BrickKind.Seal&&t.d.juiceGroup==d.juiceGroup:d.kind==BrickKind.Rainbow?(d.axis==0?dr==0:dc==0):dr<=(d.kind==BrickKind.Core?2:1)&&dc<=(d.kind==BrickKind.Core?2:1);if(affect)score+=Damage(t,d.kind==BrickKind.Switch?99:2,queue);}
   }
  }
 }
 return score;
}

System.Collections.IEnumerator InitializeOpeningGridSteps(bool incremental){
 var s=OpeningStage;InitializeOpeningTargets();InitializeOpeningThird();
 var occupiedByBoxes=new HashSet<int>();foreach(var box in s.pieces.Where(p=>p.kind=="cookie_box")){SpawnOpeningCookieBox(box);for(int y=box.r;y<box.r+2;y++)for(int x=box.c;x<box.c+2;x++)occupiedByBoxes.Add(y*9+x);}
 for(int r=0;r<9;r++){if(incremental)yield return null;for(int c=0;c<9;c++){char code=s.rows[r][c];if(code=='.')continue;var p=s.pieces.FirstOrDefault(v=>v.c==c&&v.r==r);
  if(occupiedByBoxes.Contains(r*9+c))continue;
  if(p!=null&&p.kind=="copper_coin"){SpawnOpeningCopper(p);continue;}
  if(p!=null&&p.kind=="lucky_cat"){SpawnOpeningCat(p);continue;}
  if(p!=null&&p.kind!="yarn"&&p.kind!="ingot"){var tool=SpawnChainTool(OpeningCampaign.ToolKind(p.kind),ChainGridRules.Center(c,r),OpeningCampaign.Color(code.ToString()));tool.Ingot=p.appearance=="ingot";continue;}
  CreateBrick(new BrickSpawn{position=ChainGridRules.Center(c,r),size=Vector2.one*.76f,hp=p==null||p.kind=="ingot"?OpeningCampaign.InitialHp(s,c,r):1,colorIndex=p!=null?0:OpeningCampaign.Color(code.ToString()),referenceCol=c,referenceRow=r,juiceGroup=0,reveal=p!=null?"opening-yarn":"opening-N",kind=BrickKind.Normal},0);
  if(p!=null&&p.kind=="ingot"){OpeningSetIngot(CollectionBricks.Last());continue;}
  if(p!=null){var brick=CollectionBricks.Last();var view=brick.gameObject.AddComponent<OpeningYarnView>();view.Initialize(this,brick,p.layers);openingYarn[brick.Id]=view;}
 }}
 ChainMessage=s.name+" · "+s.focus;PlanChainRow();
}

void OpeningCollect(string kind,Vector2 position,int color=-1,bool ingot=false){
 if(!IsOpening)return;
 for(int i=0;i<OpeningTargets.Length;i++){var t=OpeningTargets[i];bool match=t.kind=="ingot"?ingot:t.kind=="ordinary_color"?kind=="ordinary_color"&&!ingot&&OpeningCampaign.Color(t.color)==color:t.kind==kind;
  if(!match||OpeningCollected[i]+openingTargetPending[i]>=t.count)continue;
  openingTargetPending[i]++;var root=new GameObject("Opening collected "+t.kind).transform;root.SetParent(world,false);root.position=position;
  var sprite=OpeningTargetSprite(i);var image=ChainVisualArt.Draw(root,"Independent target collectible",sprite,.48f/Mathf.Max(.01f,sprite.bounds.size.x),75);image.sharedMaterial=OpeningYarnArt.Material;
  // A thin cream silhouette keeps the flying object readable over same-colour bricks.
  var edge=new GameObject("Soft collectible rim").AddComponent<SpriteRenderer>();edge.transform.SetParent(root,false);edge.sprite=sprite;edge.sharedMaterial=SevenSpecialArt.Material(sprite);edge.sortingOrder=image.sortingOrder-1;edge.transform.localScale=image.transform.localScale*1.12f;edge.color=new Color(1,1,1,.82f);var block=new MaterialPropertyBlock();block.SetFloat("_Flash",1);edge.SetPropertyBlock(block);
  int creditedTarget=i;chainLoot.Add(new ChainLoot{OpeningTarget=i,Start=position,View=root,StrategyCredit=StrategyObserver==null?null:StrategyWrap(()=>OpeningCreditTarget(creditedTarget))});changed=true;
 }
}

public void TickOpeningThird(float dt){
 if(!IsOpening||IsPaused||!IsPlaying&&!VictorySettlementActive||dt<=0)return;
 foreach(var cat in openingCats)if(cat!=null)cat.TickImpact(dt);
 if(OpeningGoalsEarned)foreach(var c in openingCats)c.Queued=c.PendingIngots=0;
 if(openingCasts.Count==0)BeginCatBatch();
 foreach(var cast in openingCasts.ToArray()){
  cast.Age+=dt;cast.Cat.WaveAge=cast.Age;
  if(!cast.Light&&cast.Age>=CatWindup){cast.Light=true;OpeningPlayRing(cast.Cat.transform.position);SoundService.Play("lucky_cat_cast");}
  foreach(var f in cast.Flights){
   if(f.Cancelled)continue;
   if(!f.Arrived&&!TrackCatTarget(f)&&!RetargetCatFlight(f,cast.Age)){
    // A live clear may temporarily exhaust all legal targets. Preserve only
    // this undelivered ingot, without holding the board or settlement open.
    f.Arrived=f.Cancelled=true;f.LandAge=cast.Age;cast.Cat.PendingIngots++;openingCatWaitingForSpace=true;f.Image.enabled=f.Ray.enabled=false;ScheduleChainGravity();continue;
   }
   float rayProgress=Mathf.Clamp01((cast.Age-CatWindup)/.10f);var rayTip=Vector2.Lerp(f.Start,f.End,rayProgress*.38f);var rayDelta=rayTip-f.Start;f.Ray.transform.position=(f.Start+rayTip)*.5f;f.Ray.transform.rotation=Quaternion.Euler(0,0,Mathf.Atan2(rayDelta.y,rayDelta.x)*Mathf.Rad2Deg);f.Ray.transform.localScale=new Vector3(rayDelta.magnitude,.045f,1);f.Ray.color=new Color(1,.79f,.16f,Mathf.Clamp01((.40f-cast.Age)/.10f));float u=Mathf.Clamp01((cast.Age-f.Delay)/f.Duration);if(cast.Age<f.Delay)continue;f.Image.enabled=true;
   Vector2 control=f.Start+Vector2.up*(.75f+Vector2.Distance(f.Start,f.End)*.2f);f.Image.transform.position=(1-u)*(1-u)*f.Start+2*(1-u)*u*control+u*u*f.End;
   float size=Mathf.Lerp(.018f,.76f,u*u);if(u>=1){if(!f.Arrived){IngotDisplace(f);f.Arrived=true;f.LandAge=cast.Age;}float t=Mathf.Clamp01((cast.Age-f.LandAge)/CatTail);size=.76f*(1+Mathf.Sin(t*Mathf.PI)*.13f);f.Image.color=new Color(1,1,1,1-t);}
   OpeningThirdArt.Fit(f.Image,"ingot",OpeningThirdArt.Variant(f.Tool?.Kind??0),size);
  }
  if(cast.Age>=.8f&&cast.Flights.All(f=>f.Arrived&&cast.Age>=f.LandAge+CatTail)){cast.Cat.WaveAge=-1;foreach(var f in cast.Flights){if(f.Image!=null)Destroy(f.Image.gameObject);if(f.Ray!=null)Destroy(f.Ray.gameObject);}openingCasts.Remove(cast);}
 }
 foreach(var ghost in openingGhosts.ToArray()){ghost.Age+=dt;float t=ghost.Age/.55f;ghost.Image.transform.position=ghost.Start+ghost.Velocity*ghost.Age+Vector2.down*5*ghost.Age*ghost.Age;ghost.Image.transform.localRotation=Quaternion.Euler(0,0,ghost.Spin*ghost.Age);ghost.Image.color=new Color(1,1,1,1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.08f,.55f,ghost.Age)));if(t>=1){Destroy(ghost.Image.gameObject);openingGhosts.Remove(ghost);}}
 foreach(var ring in openingRings.ToArray()){ring.Age+=dt;OpeningThirdArt.Fit(ring.Image,"ring",Mathf.Clamp((int)(ring.Age*24),0,15),2.0f);if(ring.Age>=16f/24){Destroy(ring.Image.gameObject);openingRings.Remove(ring);}}
}

 public void Tick(float dt){if(!owner.IsPlaying||owner.IsPaused||!Brick.Alive)return;
 wobble+=dt;
 if(box.bounds.min.x>FlightGeometry.Right||box.bounds.max.x<FlightGeometry.Left){owner.RecyclePixelDrop(this);return;}
 if(!Detached){Vector2 delta=anchor-Body.position;float softness=.7f+.3f*Stability/grade;
 Body.AddForce((delta*(30f*softness)-Body.linearVelocity*7f)*Body.mass);
 Body.AddTorque((-Mathf.DeltaAngle(0,Body.rotation)*.12f-Body.angularVelocity*.065f)*Body.mass);
 // Large displacement/rotation can tear a weakened tether before its nominal count reaches zero.
 if(delta.magnitude>.18f+.085f*Stability||Mathf.Abs(Mathf.DeltaAngle(0,Body.rotation))>30+Stability*9)Detach();
 }else{
 // Table friction opposes motion in both axes; no vertical force or automatic drift.
 var v=Body.linearVelocity;Body.linearVelocity=Vector2.MoveTowards(v,Vector2.zero,(.65f+.12f*Body.mass)*dt);
 Body.angularVelocity=Mathf.MoveTowards(Body.angularVelocity,0,45*dt);
 }
 if(Body.position.y>FlightGeometry.Top-.4f){Body.position=new Vector2(Body.position.x,FlightGeometry.Top-.4f);Body.linearVelocity=new Vector2(Body.linearVelocity.x,-Mathf.Abs(Body.linearVelocity.y)*.8f);}
 if(Body.position.y<FlightGeometry.ReturnY+.4f){Body.position=new Vector2(Body.position.x,FlightGeometry.ReturnY+.4f);Body.linearVelocity=new Vector2(Body.linearVelocity.x,Mathf.Abs(Body.linearVelocity.y)*.8f);}

 }

void LateUpdate(){if(owner==null||owner.IsPaused||!Brick.Alive)return;
float f=grade<=2?20:15;float pulse=Mathf.Exp(-wobble*5)*Mathf.Cos(wobble*f)*(.22f/Mathf.Sqrt(Body.mass));
// Rotate the visual deformation axes; the collider retains its rigid square shape.
visual.localRotation=Quaternion.Euler(0,0,axis);Brick.Face.transform.localRotation=Quaternion.Euler(0,0,-axis);
visual.localScale=new Vector3(1-pulse,1+pulse,1);Brick.Face.transform.localScale=faceScale;
}

public IEnumerator Run(Action<Action,Action<string>> begin,float timeout=15){
 float deadline=Time.realtimeSinceStartup+timeout;
 try{
  try{begin(()=>{if(!resolved){resolved=true;Succeeded=true;}},message=>{if(!resolved){resolved=true;Error=message;}});}catch(Exception error){resolved=true;Error=error.Message;}
  while(!resolved&&Time.realtimeSinceStartup<deadline)yield return null;
  if(!resolved){resolved=true;Error="初始化等待超时，请重试。";}
 }finally{resolved=true;}
}

IEnumerator Start(){
 var args=Environment.GetCommandLineArgs();dir=args[Array.IndexOf(args,"--qa-out")+1];Directory.CreateDirectory(dir);File.WriteAllText(dir+"/checks.txt","");Application.logMessageReceived+=(m,s,t)=>{if(t==LogType.Error||t==LogType.Exception){errors++;File.AppendAllText(dir+"/errors.txt",m+"\n"+s+"\n");}};
