public static IEnumerator Run(GameSession game, string output, Action<string, bool, string> check) {
    try { Data(output, check); } catch (Exception e) { Assert(check, "authoring executes", false, e.ToString()); }
    foreach (string variant in new[] { "finite3", "unlimited3", "legacy_missing9", "useful_finite3", "useful_unlimited3", "ordinary_line" }) {
        try {
            if (variant.StartsWith("useful_", StringComparison.Ordinal)) Useful(game, check, variant == "useful_finite3");
            else if (variant == "ordinary_line") OrdinaryLine(game, check);
            else Collision(game, check, variant);
        } catch (Exception e) { Assert(check, variant + " executes", false, e.ToString()); }
        game.StopLevel(); game.BoosterProfile = null; yield return null;
    }
}

// All three firing modes call this same visible-board heuristic with identical weights.
public static BalanceAim Choose(GameSession g,BalanceWeights w,System.Random random){
 var bricks=g.CollectionBricks.Where(b=>b!=null&&b.Alive&&b.gameObject.activeInHierarchy&&b.GetComponent<BoxCollider2D>()?.enabled!=false&&b.GetComponent<ChainTileVisibility>()?.Hidden!=true).ToArray();
 var positions=new Vector2[bricks.Length];var halves=new Vector2[bricks.Length];var gains=new Vector2[bricks.Length];
 for(int n=0;n<bricks.Length;n++){var b=bricks[n];var body=b.GetComponent<Rigidbody2D>();positions[n]=body!=null?body.position:(Vector2)b.transform.position;var box=b.GetComponent<BoxCollider2D>();halves[n]=box!=null?box.size*.5f:Vector2.one*.38f;gains[n]=g.BalanceVisibleGains(b);}
 var tools=g.ChainTools.Where(t=>!t.Consumed&&!t.Waiting&&t.View!=null&&t.View.gameObject.activeInHierarchy&&t.View.GetComponent<ChainTileVisibility>()?.Hidden!=true).ToArray();
 var toolValues=new float[tools.Length];
 for(int t=0;t<tools.Length;t++){
  var tool=tools[t];float value=0;
  for(int n=0;n<bricks.Length;n++){
   var d=positions[n]-tool.Position;bool covered=tool.Kind==SevenSpecialRules.Horizontal?Mathf.Abs(d.y)<.5f:tool.Kind==SevenSpecialRules.Vertical?Mathf.Abs(d.x)<.5f:tool.Kind==SevenSpecialRules.Cross?Mathf.Abs(d.x)<.5f||Mathf.Abs(d.y)<.5f:tool.Kind==SevenSpecialRules.Bomb?Mathf.Abs(d.x)<1.3f&&Mathf.Abs(d.y)<1.3f:bricks[n].Definition.colorIndex==tool.ColorIndex;
   if(covered)value+=gains[n].x+gains[n].y;
  }
  int partners=tools.Count(other=>other!=tool&&SevenSpecialRules.Nearby(other.Position,tool.Position));
  toolValues[t]=w.special*(1+Mathf.Min(3,value/8))+w.combo*Mathf.Min(2,partners);
 }
 var best=new BalanceAim{Direction=Vector2.up,Utility=float.NegativeInfinity};float bestTool=0;
 for(int i=0;i<w.directions;i++){
  float angle=Mathf.Lerp(15,165,(i+.2f+(float)random.NextDouble()*.6f)/w.directions)*Mathf.Deg2Rad;var direction=new Vector2(Mathf.Cos(angle),Mathf.Sin(angle));var origin=g.SpawnPosition(direction);
  int hit=-1;float nearest=100;
  for(int n=0;n<bricks.Length;n++)if(RayBox(origin,direction,positions[n],halves[n],out float distance)&&distance<nearest){nearest=distance;hit=n;}
  float utility=0,specialValue=0;int kind=0;
  if(hit>=0){var first=bricks[hit];bool immune=g.OpeningYarnBrick(first)||g.OpeningCookieBrick(first)||g.OpeningCatBrick(first);float clear=immune?0:1f/Mathf.Max(1,first.CurrentHealth);
   utility=w.direct*clear+w.target*gains[hit].x*clear;
   if(clear>0)for(int n=0;n<bricks.Length;n++)if(n!=hit&&Adjacent(positions[hit],positions[n],halves[n]))utility+=w.adjacent*gains[n].y*clear;
  }
  for(int t=0;t<tools.Length;t++){var d=tools[t].Position-origin;float along=Vector2.Dot(d,direction);if(along>0&&along<nearest+.4f&&Mathf.Abs(d.x*direction.y-d.y*direction.x)<.45f){specialValue=Mathf.Max(specialValue,toolValues[t]);kind=tools[t].Kind;}}
  bestTool=Mathf.Max(bestTool,specialValue);utility+=specialValue+(float)random.NextDouble()*w.noise;
  if(utility>best.Utility)best=new BalanceAim{Direction=direction,Utility=utility,Kind=kind};
 }
 best.SpecialOpportunity=Mathf.Clamp01(bestTool/Mathf.Max(.01f,w.special*3));return best;
}

IEnumerator Run(){
 Active=true;BalanceClock.Active=true;Application.runInBackground=true;Application.logMessageReceived+=OnLog;
 if(LevelEditorRuntime.HasArg("--balance-selfcheck")){int failures=OpeningBalanceChecks.Run(LevelEditorRuntime.Arg("--qa-out"));Application.Quit(failures==0?0:3);yield break;}
 string path=LevelEditorRuntime.Arg("--balance-request");
 try{request=JsonUtility.FromJson<BalanceRequest>(File.ReadAllText(path));
  if(request.first<1||request.last>45||request.first>request.last||request.trials<1||request.trials>10000||request.maxSteps<600||(request.requestVersion!=2||request.policy!="advanced"||!new[]{"all","rapid","settled","hybrid"}.Contains(request.fireMode))||!new[]{"screen","validation","holdout"}.Contains(request.split))throw new ArgumentException("Invalid balance request");
  request.weights.Validate();Directory.CreateDirectory(request.output);OpeningCampaign.LoadBalanceData(File.ReadAllText(request.input));
 }catch(Exception e){Debug.LogError(e);Application.Quit(2);yield break;}
 
 Physics2D.simulationMode=SimulationMode2D.Script;Time.fixedDeltaTime=1f/60;Time.timeScale=0;
 SoundService.SetMuted(true);AlphabetTypography.Install();
 var modes=request.fireMode=="all"?new[]{"rapid","settled","hybrid"}:new[]{request.fireMode};
 string requestHash=Hash(File.ReadAllText(path));
 foreach(int level in Enumerable.Range(request.first,request.last-request.first+1))foreach(string mode in modes)for(int trial=0;trial<request.trials;trial++){
  string resultPath=Path.Combine(request.output,$"L{level:00}-{mode}-{trial:0000}.json");
  if(File.Exists(resultPath)){var old=JsonUtility.FromJson<BalanceRun>(File.ReadAllText(resultPath));if(old.requestHash!=requestHash)throw new InvalidOperationException("Resume request mismatch");continue;}
  int seed=unchecked(request.seed+level*100003+trial*7919+(request.split=="screen"?0:request.split=="validation"?100000000:200000000));
  UnityEngine.Random.InitState(seed);var root=new GameObject("Isolated balance session");
  game=root.AddComponent<GameSession>();game.enabled=false;game.QAIgnoreFocusLoss=true;
  game.BoosterProfile=LocalProfile.CreateLevelEditorProfile(level-1,"bare");
  game.StartLevel(level-1);game.BalanceSeed(seed);
  StrategyRound strategyData=null;PlayerStrategyRecorder strategyRecorder=null;
  if(request.recordPlayerStrategy){strategyData=new StrategyRound{engineHash=PlayerStrategyReport.EngineFingerprint,platform=Application.platform.ToString()};strategyRecorder=new PlayerStrategyRecorder(game,strategyData);game.StrategyObserver=strategyRecorder.Observe;}game.SetPaused(false);game.CombatFeel?.CancelStop();
  outcome=won=false;game.Outcome+=OnOutcome;int initialErrors=errorCount,step=0,nextCheck=0,stable=0,lastShot=-100000,lastProgress=0,waitSteps=0,maxGroups=0;var shots=new List<BalanceShot>();
  while(!outcome&&step<request.maxSteps&&errorCount==initialErrors){
   stable=game.BalanceFullySettled?stable+1:0;BalanceShot attempt=null;int beforeShots=game.Shots;
   if(step>=nextCheck&&game.ChainCanLaunch){
    float since=(step-lastShot)*Time.fixedDeltaTime;int used=game.CurrentLevel.initialShots-game.Shots;
    bool settled=stable*Time.fixedDeltaTime>=request.weights.stableSeconds;
    if(since+.0001f>=request.weights.interval&&(mode!="settled"||settled)){
     // Waiting does not consume a different aiming RNG stream. The same shot
     // index receives the same candidate angles/noise in all firing modes.
     var aim=BalanceFirePolicy.Choose(game,request.weights,new System.Random(unchecked(seed^(used+1)*1640531527)));
     var state=new BalanceTimingState{CanLaunch=true,Settled=settled,Groups=game.ChainLiveGroups,Moving=game.BalanceBoardMoving,Effects=game.BalanceEffectsPending,PendingRewardGroups=game.BalancePendingRewardGroups,Progress=game.BalanceGoalProgress>lastProgress,SinceShot=since,SpecialOpportunity=aim.SpecialOpportunity};
     if(BalanceFirePolicy.ShouldFire(mode,state,request.weights,out string reason)&&game.TryShoot(aim.Direction))attempt=new BalanceShot{step=step,used=used+1,x=aim.Direction.x,y=aim.Direction.y,score=game.Score,collected=(int[])game.OpeningCollected.Clone(),activeBalls=game.ActiveBalls,liveGroups=game.ChainLiveGroups,settled=settled,reason=reason,utility=aim.Utility,availableSpecials=game.ChainTools.Count(t=>!t.Consumed&&!t.Waiting)};
     else waitSteps+=6;
     nextCheck=step+6;
    }else if(mode!="rapid")waitSteps++;
   }
   try{strategyRecorder?.Tick(Time.fixedDeltaTime,true);game.BalanceStep();}catch(Exception e){Debug.LogError(e);}
   if(attempt!=null&&game.Shots<beforeShots){shots.Add(attempt);lastShot=step;lastProgress=attempt.collected.Sum();}
   maxGroups=Math.Max(maxGroups,game.ChainLiveGroups);step++;if(step%300==0)yield return null;
  }
  int score=game.Score;bool valid=outcome&&errorCount==initialErrors;
  if(valid)game.FinalizeScore(won);
  var row=new BalanceRun{level=level,trial=trial,seed=seed,policy="advanced",fireMode=mode,weightsHash=request.weightsHash,policyVersion=PolicyVersion,overlapShots=shots.Count(s=>s.liveGroups>0||s.activeBalls>0),settledShots=shots.Count(s=>s.settled),waitSteps=waitSteps,maxLiveGroups=maxGroups,split=request.split,status=errorCount>initialErrors?"error":!outcome?"timeout":won?"win":"loss",error=errorCount>initialErrors?lastError:null,
   requestHash=requestHash,diagnostics=valid?null:game.VictorySettlementStatus+"\n"+game.QARefillStatus(),levelHash=Hash(JsonUtility.ToJson(OpeningCampaign.Stage(level-1))),steps=step,seconds=step*Time.fixedDeltaTime,
   used=game.CurrentLevel.initialShots-game.Shots,remaining=game.Shots,scoreAtOutcome=score,scoreWithSpareBonus=game.Score,spareBonus=game.CreditedCompletionBonus,
   damageScore=game.DamageScore,breakScore=game.BreakScore,objectiveScore=game.ObjectiveScore,hits=game.HitCount,breaks=game.BreakCount,activations=game.ChainActivationCount,
   refills=game.ChainRefills,ingotConversions=game.OpeningIngotConversions,goals=game.OpeningTargets,collected=(int[])game.OpeningCollected.Clone(),shots=shots.ToArray()};
  if(strategyData!=null){var history=new BalanceHistory();history.rounds.Add(new BalanceRound{id=$"batch-{level}-{mode}-{trial}",level=level,version=GameVersion.Name,configHash=row.levelHash,strategyVersion=2,strategy=strategyData,usedShots=row.used,initialShots=row.used+row.remaining,remainingShots=row.remaining,score=row.scoreAtOutcome,outcome=row.status,activeSeconds=row.seconds,configAttempt=1,goals=row.goals.Select((g,i)=>new BalanceGoal{kind=g.kind,color=g.color,required=g.count,collected=row.collected[i]}).ToArray()});File.WriteAllText(Path.Combine(request.output,$"strategy-L{level:00}-{mode}-{trial:0000}.json"),BalanceReport.Json(history));}
  File.WriteAllText(resultPath+".tmp",JsonUtility.ToJson(row,true));File.Move(resultPath+".tmp",resultPath);
  game.Outcome-=OnOutcome;game.StopLevel();Destroy(root);game=null;yield return null;
  if(trial==request.trials-1)Debug.Log($"BALANCE_PROGRESS level={level} fireMode={mode} trials={request.trials}");
  if(File.Exists(Path.Combine(request.output,"cancel.request"))){File.WriteAllText(Path.Combine(request.output,"cancelled.json"),"{\"status\":\"cancelled\"}");Application.Quit(0);yield break;}
 }
 File.WriteAllText(Path.Combine(request.output,"complete.json"),"{\"status\":\"complete\",\"policyVersion\":\""+PolicyVersion+"\"}");
 Debug.Log("LEVEL_BALANCE_COMPLETE");Application.Quit(errorCount==0?0:3);
}

void Awake()
{
    Application.targetFrameRate = 60;
    Application.runInBackground = true;
    qaMode = HasArgument("--level-editor-qa");
    rootDirectory = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments), "BounceBustersLevelEditor");
    if (qaMode) rootDirectory = Argument("--level-editor-qa-out") ?? Path.Combine(Path.GetTempPath(), "BounceBustersLevelEditorQA");
    workspaceDirectory = Argument("--level-editor-workspace") ?? Path.Combine(rootDirectory, "Projects", "MyLevels");
    if (!qaMode && Argument("--level-editor-workspace") == null)
    {
        try { var path = Path.Combine(rootDirectory, "authoring-settings.json"); if (File.Exists(path)) { var settings = JsonUtility.FromJson<WorkspaceSettings>(File.ReadAllText(path)); if (!string.IsNullOrWhiteSpace(settings.workspace)) workspaceDirectory = settings.workspace; } }
        catch (Exception ex) { Debug.LogWarning("Level editor workspace preference: " + ex.Message); }
    }
    exportParent = Path.Combine(rootDirectory, "Exports");
    Playtest = gameObject.AddComponent<LevelEditorPlaytest>();
    Playtest.Completed += OnCompleted;
    try
    {
        Directory.CreateDirectory(rootDirectory);
        bool anyCampaign = Directory.Exists(workspaceDirectory) && Directory.GetFiles(workspaceDirectory, "campaign.json", SearchOption.AllDirectories).Length > 0;
        Workspace = anyCampaign ? LevelEditorWorkspace.LoadDirectory(workspaceDirectory) : LevelEditorWorkspace.CreateEmpty();
        if (anyCampaign && string.IsNullOrEmpty(Workspace.LastSaveDirectory)) workspaceDirectory = Path.Combine(rootDirectory, "Imports", DateTime.Now.ToString("yyyyMMdd-HHmmss-fff"));
        if (!anyCampaign || string.IsNullOrEmpty(Workspace.LastSaveDirectory))
        {
            var saved = Workspace.SaveWorkspace(workspaceDirectory);
            if (!saved.Success) throw new IOException(saved.Message);
        }
        loaded = true; SelectLevel(0);
        RememberWorkspace();
        SetStatus(Workspace.Levels.Count == 0 ? "新项目已就绪 · 选择规则模板，点击「＋ 新建关卡」从空棋盘开始" : "已载入 " + Workspace.Levels.Count + " 关 · 草稿每 15 秒自动保存 · " + workspaceDirectory);
    }
    catch (Exception ex) { SetStatus("工作区载入失败：" + ex.Message, true); }
    nextSave = Time.unscaledTime + 15;
    Application.wantsToQuit += CanQuit;
}

void Update()
{
    // A release outside the native window may not deliver a GUI MouseUp.
    if (gestureLevel != null && !Input.GetMouseButton(0) && !Input.GetMouseButtonUp(0)) FinishBoardGesture();
    if (loaded && !qaMode && !IsPlaytesting && gestureLevel == null && Time.unscaledTime >= nextSave)
    {
        nextSave = Time.unscaledTime + 15;
        if (Workspace.IsDirty) SaveWorkspace();
    }
    if (IsPlaytesting && Camera.main != null)
    {
        var rect = previewRect;
        Camera.main.rect = new Rect(rect.x * scale / Screen.width, 1 - (rect.y + rect.height) * scale / Screen.height,
            rect.width * scale / Screen.width, rect.height * scale / Screen.height);
    }
}

public bool BeginPlaytest()
{
    if (CurrentLevel == null || IsPlaytesting) return false;
    FinishBoardGesture();
    RefreshValidation();
    if (issues.Any(p => p.IsError)) { SetStatus("请先修复当前关卡的校验错误，再开始试玩。", true); return false; }
    if (!SaveWorkspace()) return false;
    string snapshot = CurrentLevel.SnapshotJson();
    if (!Playtest.StartDraft(CurrentLevel, Scenarios[scenario])) { SetStatus(Playtest.LastError, true); return false; }
    IsPlaytesting = true; aiming = false; runStart = Time.unscaledTime; recordWritten = false;
    fusionPlayScroll = Vector2.zero;
    shotRecords.Clear(); runScenario = Scenarios[scenario];
    using (var hash = SHA256.Create()) runHash = BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(snapshot))).Replace("-", "").ToLowerInvariant();
    Playtest.Session.VolleyStarted -= OnVolley; Playtest.Session.VolleyStarted += OnVolley;
    if (Camera.main != null) Camera.main.enabled = true;
    SetStatus("真实试玩 · 按住棋盘瞄准，松开发射 · 道具需手动选择 · Esc 返回编辑");
    return true;
}

void OnVolley(StreakBooster booster)
{
    shotRecords.Add(new ShotRecord { elapsedSeconds = Time.unscaledTime - runStart, booster = booster.ToString(),
        remainingShots = Playtest.Session.Shots, hits = Playtest.Session.HitCount, breaks = Playtest.Session.BreakCount,
        collected = (int[])Playtest.Session.Collected.Clone(), jellyCollected = (int[])Playtest.Session.JellyCollected.Clone() });
}

