public static int Run(string directory){
 Directory.CreateDirectory(directory);var checks=new List<string>();int failures=0;
 Action<bool,string> check=(ok,name)=>{checks.Add((ok?"PASS ":"FAIL ")+name);if(!ok)failures++;};
 var root=new GameObject("Balance regression checks");var game=root.AddComponent<GameSession>();game.enabled=false;game.QAIgnoreFocusLoss=true;
 Physics2D.simulationMode=SimulationMode2D.Script;Time.fixedDeltaTime=1f/60;Time.timeScale=0;
 try{
  var data=JsonUtility.FromJson<OpeningData>(JsonUtility.ToJson(OpeningCampaign.Data));var s=data.levels[0];s.health=new OpeningHealth{ordinaryHp=3,refillHp=5};s.hpOverrides=new[]{new OpeningHpOverride{c=4,r=4,hp=7}};
  OpeningCampaign.LoadBalanceData(JsonUtility.ToJson(data));game.StartLevel(0);game.SetPaused(false);
  check(game.CollectionBricks.Where(b=>b.Definition.referenceCol==4&&b.Definition.referenceRow==4).Single().CurrentHealth==7,"local HP reaches physical brick");
  check(game.CollectionBricks.Where(b=>b.Definition.referenceCol!=4||b.Definition.referenceRow!=4).All(b=>b.CurrentHealth==3),"ordinary HP reaches every other physical brick");
  check(game.BalanceCheckRefillHp()==5,"refill HP reaches actual spawned body");
  game.StartLevel(37);game.SetPaused(false);game.BalanceCheckPendingArrival(check);game.BalanceCheckWaitingRoute(check);
  data.levels[0].health=null;data.levels[0].hpOverrides=null;OpeningCampaign.LoadBalanceData(JsonUtility.ToJson(data));game.StartLevel(0);
  check(game.CollectionBricks.All(b=>b.CurrentHealth==1),"old levels keep one-hit default");
  game.BalanceCheckSeeds(check);
  var weights=new BalanceWeights();var timing=new BalanceTimingState{CanLaunch=true,Groups=1,SinceShot=2};
  check(BalanceFirePolicy.ShouldFire("rapid",timing,weights,out _),"rapid mode permits overlapping groups");
  check(!BalanceFirePolicy.ShouldFire("settled",timing,weights,out _),"settled mode rejects an unfinished previous group");
  timing.Groups=0;timing.Settled=true;check(BalanceFirePolicy.ShouldFire("settled",timing,weights,out _),"settled mode fires after complete settlement");
  timing.Groups=1;timing.Settled=false;check(BalanceFirePolicy.ShouldFire("hybrid",timing,weights,out _),"hybrid can overlap on an open board");
  timing.SpecialOpportunity=1;timing.Effects=true;timing.Moving=true;check(!BalanceFirePolicy.ShouldFire("hybrid",timing,weights,out _),"hybrid waits for a valuable special/settlement opportunity");
  timing.Groups=weights.hybridMaxGroups;check(!BalanceFirePolicy.ShouldFire("hybrid",timing,weights,out _),"hybrid respects its live-group cap");
  check(BalanceFirePolicy.RayBox(Vector2.zero,Vector2.up,new Vector2(.7f,3),Vector2.one*.82f,out float distance)&&Mathf.Abs(distance-2.18f)<.001f,"aiming respects the whole 2x2 box footprint");
 }catch(Exception e){check(false,e.ToString());}
 finally{game.StopLevel();UnityEngine.Object.Destroy(root);}
 File.WriteAllLines(Path.Combine(directory,"checks.txt"),checks);File.WriteAllText(Path.Combine(directory,"summary.json"),"{\"checks\":"+checks.Count+",\"failures\":"+failures+"}");
 Debug.Log("OPENING_BALANCE_CHECKS "+checks.Count+" failures="+failures);return failures;
}

IEnumerator Start(){
 var args=Environment.GetCommandLineArgs();dir=args[Array.IndexOf(args,"--qa-out")+1];Directory.CreateDirectory(dir);File.WriteAllText(dir+"/checks.txt","");
 Application.logMessageReceived+=(m,s,t)=>{if(t==LogType.Exception||t==LogType.Error){result.errors++;result.messages.Add(m);}};
 Application.targetFrameRate=60;QualitySettings.vSyncCount=0;yield return new WaitForSecondsRealtime(3);
 app=FindFirstObjectByType<AppUI>();
 // Returning during a partially constructed board must dispose that generation.
 app.QAStartLevel(0);float cancelDeadline=Time.realtimeSinceStartup+5;
 while(!app.Session.IsPlaying&&Time.realtimeSinceStartup<cancelDeadline)yield return null;
 Check(app.Session.IsPlaying&&app.GetComponentInChildren<LoadingPresentation>()!=null,"cancellation fixture reaches partial board construction");
 app.QANavigate("home");yield return null;yield return null;
 Check(app.CurrentPage=="home"&&!app.Session.IsPlaying&&app.GetComponentInChildren<LoadingPresentation>()==null,"cancel entry returns home without a live partial board");
 for(int index=0;index<OpeningCampaign.Count;index++){
  app.QAStartLevel(index);float start=Time.realtimeSinceStartup,deadline=start+12;entering=true;int frames=0;
  while(Time.realtimeSinceStartup<deadline){
   var loading=app.GetComponentInChildren<LoadingPresentation>();
   // A disabled presentation used to make the reveal wait depend on an Update that never ran.
   if(index==0&&loading!=null)loading.enabled=false;
   if(loading==null&&app.CurrentPage=="battle"&&app.Session.LevelIndex==index)break;
   frames++;yield return null;
  }
  entering=false;float duration=Time.realtimeSinceStartup-start;result.maxEntrySeconds=Mathf.Max(result.maxEntrySeconds,duration);
  Check(app.CurrentPage=="battle"&&app.Session.LevelIndex==index&&app.GetComponentInChildren<LoadingPresentation>()==null,"level "+(index+1)+" loading handoff "+duration.ToString("F2")+"s frames="+frames);
  Check(app.Session.ChainOccupiedCells()>0,"level "+(index+1)+" board exists");
  for(int n=0;n<90;n++){app.QAAdvanceAlphabetIntro();app.QAAdvanceBoosterGuide();if(n>8&&!app.AlphabetIntroActive&&!app.Session.IsPaused)break;yield return null;}
  app.Session.QAIgnoreFocusLoss=true;Check(!app.Session.IsPaused,"level "+(index+1)+" accepts gameplay after introductions");result.levels++;
  app.QANavigate("home");yield return null;
  if(result.failures>0)break;
 }
 File.WriteAllText(dir+"/result.json",JsonUtility.ToJson(result,true));Application.Quit(result.failures+result.errors==0?0:3);
}

IEnumerator Start(){var args=Environment.GetCommandLineArgs();dir=args[Array.IndexOf(args,"--qa-out")+1];Directory.CreateDirectory(dir);File.WriteAllText(dir+"/checks.txt","");Application.targetFrameRate=60;QualitySettings.vSyncCount=0;Application.logMessageReceived+=(m,s,t)=>{if(t==LogType.Error||t==LogType.Exception){errors++;File.AppendAllText(dir+"/errors.txt",m+"\n"+s);}};yield return new WaitForSecondsRealtime(3);app=FindFirstObjectByType<AppUI>();
 int selected=Array.IndexOf(args,"--qa-case");int firstCase=selected<0?0:int.Parse(args[selected+1]);int lastCase=selected<0?10:firstCase+1;
 for(int mode=firstCase;mode<lastCase;mode++){
  app.QAStartLevel(4);yield return app.QAWaitForLevel();var g=app.Session;g.QAIgnoreFocusLoss=true;
  for(int i=0;i<120;i++){app.QAAdvanceAlphabetIntro();app.QAAdvanceBoosterGuide();yield return new WaitForSecondsRealtime(.02f);if(i>10&&!app.AlphabetIntroActive&&!g.IsPaused)break;}g.SetPaused(false);
  if(mode>=4&&mode<8){
   // Remove the actual yarns and surrounding cells, preserving their arrival
   // callbacks and the live gravity paths at the instant the goal is earned.
   for(int batch=0;batch<3;batch++){
    var neighbours=g.QAOpeningYarns().SelectMany(y=>g.QAOpeningNeighbours(y)).Distinct().ToArray();g.QAOpeningBatch(neighbours);
    yield return new WaitForSecondsRealtime(.08f);
   }
  }
  Check(g.TryShoot(Vector2.up),"level five volley starts "+mode);yield return new WaitForSecondsRealtime(mode==0?.04f:.65f);
  if(mode>=8)g.QAVictoryLateFlowerWindup();else if(mode>=2)g.QAFinaleSpecialRound();g.QAFinaleGoal(7,39200);float start=Time.realtimeSinceStartup;
  while(g.IsPlaying&&Time.realtimeSinceStartup-start<2)yield return null;
  Check(g.VictorySettlementActive,"winning with live balls starts settlement "+mode);if(mode%2==1)g.AccelerateVictoryPlayback();
  while(app.QAVictoryPage==null&&Time.realtimeSinceStartup-start<30){if(Time.frameCount%120==0)File.AppendAllText(dir+"/state.txt","mode="+mode+" t="+(Time.realtimeSinceStartup-start)+" phase="+(app.QAVictoryPreparation!=null?app.QAVictoryPreparation.Phase:-1)+" replacements="+g.ChainPendingReplacements+" "+g.QARefillStatus()+"\n");yield return null;}
  Check(app.QAVictoryPage!=null,"level five reaches results "+mode);Check(g.ScoreFinalized&&g.Shots==0&&g.VictoryBoardSwept,"steps rewarded and board cleared "+mode);
 }
 File.WriteAllText(dir+"/result.json","{\"checks\":"+checks+",\"failures\":"+failures+",\"errors\":"+errors+"}");Application.Quit(failures==0&&errors==0?0:3);
}

IEnumerator Start(){
 string directory=Arg("--qa-out"),stage=Arg("--lifecycle"),scenario=Arg("--case");Directory.CreateDirectory(directory);
 if(LocalProfile.PersistentTestKey==null)throw new Exception("Refusing lifecycle test without isolated persistent key");
 yield return new WaitForSecondsRealtime(.5f);var app=FindFirstObjectByType<AppUI>();var profile=app.Profile;
 if(stage=="verify"){
  var before=JsonUtility.FromJson<Snapshot>(File.ReadAllText(Path.Combine(directory,"checkpoint.json")));
  int expected=scenario=="before"?1580:scenario=="complete"?1620:1600;
  bool pass=before.passed&&profile.StorageHealthy&&profile.Coins==expected&&profile.Coins==before.coins&&profile.Badges==(scenario=="before"?0:1)&&profile.UnlockedLevel==(scenario=="before"?0:1)&&profile.CommittedTransactionCount==(scenario=="before"?0:scenario=="complete"?2:1);
  if(scenario!="before")pass&=!profile.CommitBase(before.key,0);
  int coins=profile.Coins;LocalMockServices.ResolveAd(profile,before.key,MockOutcome.Cancelled);LocalMockServices.ResolveAd(profile,before.key,MockOutcome.Failed);pass&=profile.Coins==coins;
  if(scenario=="complete")pass&=LocalMockServices.ResolveAd(profile,before.key,MockOutcome.Completed)==MockOutcome.Completed&&profile.Coins==coins;
  yield return Capture(Path.Combine(directory,"restart.png"));Write(directory,"verified.json",profile,before.key,pass);Application.Quit(pass?0:4);yield break;
 }
 if(profile.Coins!=1580||profile.CommittedTransactionCount!=0)throw new Exception("Lifecycle test key is not fresh");
