void Update(){if(visual==null)return;if(!FeedbackProfile.Active.enabledFeedback||allowed==null||!allowed()){ResetPose();return;}
 float dt=Mathf.Min(Time.unscaledDeltaTime,.04f);clock+=dt;float previous=age;age+=dt;if(previous<0&&age>=0)Celebrate();
 // Damped spring, substepped for consistent motion at low frame rates.
 float target=held?-1f:hovered?.45f:0;
 for(int n=0;n<4;n++){float step=dt*.25f;velocity+=((target-spring)*155-velocity*10)*step;spring+=velocity*step;}
 spring=Mathf.Clamp(spring,-1.4f,1.4f);
 float phase=clock*2.4f+index*1.8f;
 float idle=Mathf.Sin(phase)*.018f;
 visual.localScale=new Vector3(1+spring*.018f,1-spring*.025f,1);
 float grow=hovered?.16f:0;
 icon.localScale=new Vector3(1+grow-spring*.15f+idle,Mathf.Clamp(1+grow+spring*.21f-idle,.72f,1.21f),1);
 icon.anchoredPosition=new Vector2(iconRest.x,Mathf.Clamp(iconRest.y+Mathf.Sin(phase)*7+(hovered?18:0)+spring*19,-176+icon.rect.height*icon.localScale.y*.5f,126-icon.rect.height*icon.localScale.y*.5f));
 icon.localRotation=Quaternion.Euler(0,0,Mathf.Sin(phase*.8f)*(hovered?7:3)+velocity*1.1f);
}

public void Begin(AppUI app,AlphabetIntro intro,Action done){
 owner=app;page=intro;completed=done;started=Time.unscaledTime;
 var root=(RectTransform)transform;root.anchorMin=Vector2.zero;root.anchorMax=Vector2.one;root.sizeDelta=Vector2.zero;root.anchoredPosition=Vector2.zero;
 var mask=gameObject.AddComponent<Image>();mask.color=new Color(.025f,.02f,.015f,OpeningIntroduction.IsPage(page.id)?.68f:.87f);mask.raycastTarget=true;
 var tap=gameObject.AddComponent<Button>();tap.transition=Selectable.Transition.None;tap.targetGraphic=mask;tap.onClick.AddListener(Advance);
 group=gameObject.AddComponent<CanvasGroup>();group.alpha=0;
 content=UICraft.Root(transform,"Independent animated elements",0,0,1080,2340);
 entrance=DOTween.Sequence().SetUpdate(true).SetId(this);
 entrance.Append(DOTween.To(()=>group.alpha,x=>group.alpha=x,1,.24f));AnimatedElementCount++;
 if(OpeningIntroduction.IsPage(page.id)){BuildGardenOpening();return;}if(page.id>=301){BuildBoosterIntroduction();return;}
 if(UsesMotion){BuildMotionIntroduction();return;}
 throw new InvalidOperationException("Retired introduction page: "+page.id);
}

void Enter(RectTransform target,float delay,float initialScale){
 Vector2 settled=target.anchoredPosition;target.anchoredPosition=settled+Vector2.down*28;target.localScale=Vector3.one*initialScale;
 var alpha=target.gameObject.AddComponent<CanvasGroup>();alpha.alpha=0;alpha.blocksRaycasts=false;
 entrance.Insert(delay,target.DOAnchorPos(settled,.36f).SetEase(Ease.OutCubic));entrance.Insert(delay,target.DOScale(1,.46f).SetEase(Ease.OutBack));entrance.Insert(delay,DOTween.To(()=>alpha.alpha,v=>alpha.alpha=v,1,.3f));AnimatedElementCount++;
}

 IEnumerator ShowAlphabetIntroductions(int generation){
  if(Session.IsOpening){yield return ShowOpeningIntroduction(generation);yield break;}
  foreach(var page in AlphabetCampaign.Introductions(currentLevel)){
   if(Session.SevenSpecialActive&&(page.id==4||page.id==5||page.id==10))continue;
   if(Profile.HasAlphabetIntro(page.id))continue;
   bool complete=false;
   var root=UICraft.Root(canvasRoot,"Alphabet introduction "+page.id);
   alphabetIntroduction=root.gameObject.AddComponent<AlphabetIntroductionView>();
   alphabetIntroduction.Begin(this,page,()=>{Profile.MarkAlphabetIntro(page.id);complete=true;});
   while(!complete&&generation==viewGeneration&&alphabetIntroduction!=null)yield return null;
   if(generation!=viewGeneration){CloseAlphabetIntroduction();yield break;}
   alphabetIntroduction=null;
  }

 }

