else if(shape==2){for(int i=0;i<16;i++){float a=i*Mathf.PI*2/16;p.Add(new Vector2(Mathf.Cos(a)*.48f,Mathf.Sin(a)*.43f*(.6f+.4f*Mathf.Abs(Mathf.Sin(a)))));}}
